-- Create "users" table
CREATE TABLE "users" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "username" character varying NOT NULL, "password_hash" character varying NOT NULL, "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("id"));
-- Create index "users_username_key" to table: "users"
CREATE UNIQUE INDEX "users_username_key" ON "users" ("username");
-- Create "categories" table
CREATE TABLE "categories" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "name" character varying NOT NULL, "color" character varying NOT NULL DEFAULT '#808080', "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "user_id" bigint NULL, PRIMARY KEY ("id"), CONSTRAINT "categories_users_categories" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL);
-- Create index "category_user_id_name" to table: "categories"
CREATE UNIQUE INDEX "category_user_id_name" ON "categories" ("user_id", "name");
-- Create "budgets" table
CREATE TABLE "budgets" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "amount" double precision NOT NULL, "period" character varying NOT NULL DEFAULT 'monthly', "start_date" timestamptz NOT NULL, "end_date" timestamptz NOT NULL, "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "category_id" bigint NULL, "user_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "budgets_categories_budgets" FOREIGN KEY ("category_id") REFERENCES "categories" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "budgets_users_budgets" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create "chat_messages" table
CREATE TABLE "chat_messages" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "role" character varying NOT NULL, "message_text" character varying NOT NULL, "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "user_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "chat_messages_users_chat_messages" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create "expenses" table
CREATE TABLE "expenses" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "title" character varying NOT NULL, "amount" double precision NOT NULL, "category" character varying NULL, "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "category_id" bigint NULL, "user_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "expenses_categories_expenses" FOREIGN KEY ("category_id") REFERENCES "categories" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "expenses_users_expenses" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create "recurring_expenses" table
CREATE TABLE "recurring_expenses" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "title" character varying NOT NULL, "amount" double precision NOT NULL, "interval" character varying NOT NULL, "next_run_date" timestamptz NOT NULL, "last_run_date" timestamptz NULL, "is_active" boolean NOT NULL DEFAULT true, "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "category_id" bigint NULL, "user_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "recurring_expenses_categories_recurring_expenses" FOREIGN KEY ("category_id") REFERENCES "categories" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "recurring_expenses_users_recurring_expenses" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create "sessions" table
CREATE TABLE "sessions" ("id" character varying NOT NULL, "expires_at" timestamptz NOT NULL, "user_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "sessions_users_sessions" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
